#!/bin/zsh

BASE="$HOME/Library/Mobile Documents/iCloud~md~obsidian/Documents/familia"
QUERY="${1:-}"

python3 - "$BASE" "$QUERY" <<'PY'
import os, sys, json, re

base, query = sys.argv[1], sys.argv[2]
q = query.lower().strip()
items = []

def read_snippet(path, term):
    try:
        text = open(path, "r", encoding="utf-8", errors="ignore").read()
        text = re.sub(r"\s+", " ", text).strip()
        if not term:
            return text[:180]
        i = text.lower().find(term)
        if i == -1:
            return text[:180]
        start = max(0, i - 70)
        end = min(len(text), i + 140)
        return ("…" if start else "") + text[start:end] + ("…" if end < len(text) else "")
    except Exception:
        return ""

for root, dirs, files in os.walk(base):
    dirs[:] = [d for d in dirs if not d.startswith(".")]

    for f in files:
        if not f.lower().endswith(".md"):
            continue

        full_path = os.path.join(root, f)
        rel_path = os.path.relpath(full_path, base)
        snippet = read_snippet(full_path, q)

        haystack = f"{f} {rel_path} {snippet}".lower()
        if q and q not in haystack:
            continue

        items.append({
            "uid": full_path,
            "type": "file",
            "title": f,
            "subtitle": snippet or rel_path,
            "arg": full_path,
            "quicklookurl": full_path,
            "icon": {"type": "fileicon", "path": full_path}
        })

print(json.dumps({"items": items[:100]}))
PY
